# base-conhecimento.tf — bucket de documentos, índice vetorial e a Knowledge Base
# que os conecta. Confira a versão do provider AWS antes de aplicar: os recursos
# aws_bedrockagent_* e aws_opensearchserverless_* mudaram de shape mais de uma vez
# desde que Knowledge Bases foi lançado.

resource "aws_s3_bucket" "documentos_atendimento" {
  bucket = "cadencia-documentos-atendimento"
  tags = { squad = "atendimento", projeto = "rag-politica", lab = "L83" }
}

resource "aws_s3_bucket_versioning" "documentos_atendimento" {
  bucket = aws_s3_bucket.documentos_atendimento.id
  versioning_configuration { status = "Enabled" }
  # versionamento evita que uma sobrescrita do jurídico apague, sem histórico, a
  # versão anterior de uma política — o mesmo cuidado que o L62 já aplica ao lake.
}

# ── Índice vetorial: OpenSearch Serverless, com as duas políticas que ele exige ──
resource "aws_opensearchserverless_security_policy" "criptografia" {
  name = "cadencia-rag-criptografia"
  type = "encryption"
  policy = jsonencode({
    Rules = [{ ResourceType = "collection", Resource = ["collection/cadencia-rag-*"] }]
    AWSOwnedKey = true
  })
}

resource "aws_opensearchserverless_security_policy" "rede" {
  name = "cadencia-rag-rede"
  type = "network"
  policy = jsonencode([{
    Rules = [{ ResourceType = "collection", Resource = ["collection/cadencia-rag-*"] }]
    AllowFromPublic = false
    SourceVPCEs = [aws_ec2_managed_prefix_list.acesso_kb.id]
  }])
}

resource "aws_opensearchserverless_collection" "base_conhecimento" {
  name = "cadencia-rag-politica-atendimento"
  type = "VECTORSEARCH"
  depends_on = [
    aws_opensearchserverless_security_policy.criptografia,
    aws_opensearchserverless_security_policy.rede,
  ]
}

# ── Papel que a Knowledge Base assume para ler o S3 e chamar o modelo de embedding ──
resource "aws_iam_role" "knowledge_base" {
  name = "cadencia-rag-knowledge-base-role"
  assume_role_policy = data.aws_iam_policy_document.confianca_bedrock.json
}

resource "aws_iam_role_policy" "kb_acesso_restrito" {
  role = aws_iam_role.knowledge_base.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:ListBucket"]
        # Resource especifico do bucket de documentos — nao "arn:aws:s3:::*".
        Resource = [
          aws_s3_bucket.documentos_atendimento.arn,
          "${aws_s3_bucket.documentos_atendimento.arn}/*",
        ]
      },
      {
        Effect = "Allow"
        Action = ["bedrock:InvokeModel"]
        # Restrito ao MODELO DE EMBEDDING, nao a bedrock:* — a Knowledge Base nunca
        # gera texto de resposta, so vetoriza.
        Resource = ["arn:aws:bedrock:us-east-1::foundation-model/amazon.titan-embed-text-v2:0"]
      },
      {
        Effect = "Allow"
        Action = ["aoss:APIAccessAll"]
        Resource = [aws_opensearchserverless_collection.base_conhecimento.arn]
      },
    ]
  })
}

resource "aws_bedrockagent_knowledge_base" "politica_atendimento" {
  name     = "cadencia-politica-atendimento"
  role_arn = aws_iam_role.knowledge_base.arn

  knowledge_base_configuration {
    type = "VECTOR"
    vector_knowledge_base_configuration {
      embedding_model_arn = "arn:aws:bedrock:us-east-1::foundation-model/amazon.titan-embed-text-v2:0"
    }
  }

  storage_configuration {
    type = "OPENSEARCH_SERVERLESS"
    opensearch_serverless_configuration {
      collection_arn    = aws_opensearchserverless_collection.base_conhecimento.arn
      vector_index_name = "cadencia-politica-index"
      field_mapping {
        vector_field   = "embedding"
        text_field     = "texto"
        metadata_field = "metadados"
      }
    }
  }
}

resource "aws_bedrockagent_data_source" "documentos" {
  knowledge_base_id = aws_bedrockagent_knowledge_base.politica_atendimento.id
  name               = "documentos-juridico-e-catalogo"

  data_source_configuration {
    type = "S3"
    s3_configuration { bucket_arn = aws_s3_bucket.documentos_atendimento.arn }
  }

  vector_ingestion_configuration {
    chunking_configuration {
      chunking_strategy = "FIXED_SIZE"
      fixed_size_chunking_configuration {
        max_tokens         = 500
        overlap_percentage = 20
        # 20% de sobreposicao e o numero calibrado pela maior tabela de garantia
        # por categoria do acervo — ver a secao de prova para o efeito medido.
      }
    }
  }
}

// ServicoRespostaComCitacao.cs — chama RetrieveAndGenerate em vez de InvokeModel
// puro. A diferenca estrutural em relacao ao cliente do L81 nao e o SDK, e o que
// a chamada FAZ: busca antes de gerar, e devolve a fonte junto da resposta.

public class ServicoRespostaComCitacao
{
    private readonly AmazonBedrockAgentRuntimeClient _cliente = new();

    private const string KnowledgeBaseId = "KB7F3A9C1D";
    private const string ModeloArn =
        "arn:aws:bedrock:us-east-1:111122223333:inference-profile/us.anthropic.claude-sonnet-4-20250514-v1:0";

    // Instrucao de fundamentacao: o unico lugar do sistema que probe o modelo de
    // completar com conhecimento geral quando o contexto recuperado nao basta.
    private const string InstrucaoDeFundamentacao =
        "Responda SOMENTE com base nos trechos em $search_results$. " +
        "Se os trechos nao contiverem a resposta, diga que nao encontrou essa " +
        "informacao nos documentos da Cadência — nunca complete com conhecimento geral.";

    public async Task<RespostaComCitacao> ResponderAsync(string pergunta)
    {
        var pedido = new RetrieveAndGenerateRequest
        {
            Input = new RetrieveAndGenerateInput { Text = pergunta },
            RetrieveAndGenerateConfiguration = new RetrieveAndGenerateConfiguration
            {
                Type = RetrieveAndGenerateType.KNOWLEDGE_BASE,
                KnowledgeBaseConfiguration = new KnowledgeBaseRetrieveAndGenerateConfiguration
                {
                    KnowledgeBaseId = KnowledgeBaseId,
                    ModelArn = ModeloArn,
                    GenerationConfiguration = new GenerationConfiguration
                    {
                        PromptTemplate = new PromptTemplate { TextPromptTemplate = InstrucaoDeFundamentacao },
                    },
                },
            },
        };

        var resposta = await _cliente.RetrieveAndGenerateAsync(pedido);

        // Cada citacao aponta pro trecho (chunk) e pro documento de origem — e isso
        // que vira o link clicavel na tela do atendente, nao um resumo sem fonte.
        var citacoes = resposta.Citations
            .SelectMany(c => c.RetrievedReferences)
            .Select(r => new Citacao(r.Content.Text, r.Location.S3Location.Uri))
            .ToList();

        if (citacoes.Count == 0)
        {
            // Sem trecho recuperado, a resposta NAO sai como sugestao pronta para
            // copiar — vira "nao encontrei isso nos documentos", nunca uma invencao.
            return RespostaComCitacao.SemFonte();
        }

        return new RespostaComCitacao(resposta.Output.Text, citacoes);
    }
}
